class Solution {public:int minimumDistance(vector<vector<int>>& points){
 multiset<int> a,b;for(auto &p:points){a.insert(p[0]+p[1]);b.insert(p[0]-p[1]);}
 int ans=INT_MAX;for(auto &p:points){int x=p[0]+p[1],y=p[0]-p[1];a.erase(a.find(x));b.erase(b.find(y));
 int d=0;if(!a.empty())d=max(*a.rbegin()-*a.begin(),*b.rbegin()-*b.begin());ans=min(ans,d);a.insert(x);b.insert(y);}return ans;
}};
